/**
 * A person's name as the Daily Summary shows it: the Staff record's name, else the login name. Never decorated — no role
 * hint, no brackets, no trimming. Signers, "Generated by", the deduction authoriser and the collected-by-staff table all use
 * THIS one function (deduction people are teacher / staff names read straight from their records).
 */
export const displayName = (u: { username: string; staff?: { name: string } | null }): string => u.staff?.name ?? u.username;
